/* Storage: the MySQL database behind the Python API. Changes are sent as they happen (see sync.js). */
function hydrate(d) {
  if (d && Array.isArray(d.employees)) {
    const out = Object.assign(blank(), d);
    out.settings = Object.assign(blank().settings, d.settings || {});
    out.stat = Object.assign(defaultStatutory(), d.stat || {});
    return out;
  }
  return blank();
}
let S = blank();
const sync = createSync(() => S, {
  onRejected: (msg) => hooks.onSyncRejected(msg),
  onUnauthorised: () => hooks.onSessionEnded(),
  onOffline: () => toast('The server cannot be reached. Changes are kept and saved when it is back.'),
});
function save() { sync.schedule(); }
function saveNow() { sync.flush(); }
function audit(what, detail, module = '', refType = '', refId = '') { S.audit.unshift({ at: Date.now(), by: me ? me.id : '', what, detail, module, refType, refId }); if (S.audit.length > 1000) S.audit.length = 1000; }
function nextNo(kind, prefix) { S.seq[kind] = (S.seq[kind] || 0) + 1; return `${prefix}${String(S.seq[kind]).padStart(5, '0')}`; }

/* ---------------------------------------------------------------- people, roles and scope */
let me = null;          // signed-in employee
let CO = null;          // company being worked on (id)
const ROLES = { super: 'Group administrator', hr: 'HR administrator', employee: 'Employee' };
const empById = (id) => S.employees.find((e) => e.id === id);
const coById = (id) => S.companies.find((c) => c.id === id);
const company = () => coById(CO) || S.companies[0];
const fullName = (e) => (e ? `${e.firstName || ''} ${e.lastName || ''}`.trim() : '');
const nameOf = (id) => fullName(empById(id)) || '—';
const isSuper = () => me && me.role === 'super';
const isHR = (coId = CO) => me && (me.role === 'super' || (me.role === 'hr' && (me.companyId === coId || (me.hrCompanies || []).includes(coId))));
const reportees = (id) => S.employees.filter((e) => e.managerId === id && e.status !== 'exited');
/* Dotted-line (matrix) reporting: someone may also report to other managers besides their line manager */
const matrixReportees = (id) => S.employees.filter((e) => (e.matrixManagerIds || []).includes(id) && e.status !== 'exited');
const isManager = () => me && (reportees(me.id).length > 0 || matrixReportees(me.id).length > 0);
const companiesForMe = () => (isSuper() ? S.companies : S.companies.filter((c) => c.id === me.companyId || (me.hrCompanies || []).includes(c.id)));
const active = (e) => e.status !== 'exited';
const coEmployees = (coId = CO, all = false) => S.employees.filter((e) => e.companyId === coId && (all || active(e)));
function allReportees(id, seen = new Set()) { reportees(id).forEach((e) => { if (!seen.has(e.id)) { seen.add(e.id); allReportees(e.id, seen); } }); return [...seen]; }
/* Whom the signed-in person may see in team views: HR sees the company, managers their reporting line, others themselves */
function visibleEmps() {
  if (isHR()) return coEmployees();
  const ids = new Set([me.id, ...allReportees(me.id), ...matrixReportees(me.id).map((e) => e.id)]);
  return S.employees.filter((e) => ids.has(e.id) && active(e));
}
const dept = (id) => S.depts.find((x) => x.id === id);
const desig = (id) => S.desigs.find((x) => x.id === id);
const grade = (id) => S.grades.find((x) => x.id === id);
const loc = (id) => S.locations.find((x) => x.id === id);
const shiftById = (id) => S.shifts.find((x) => x.id === id);
const ltById = (id) => S.leaveTypes.find((x) => x.id === id);

/* ---------------------------------------------------------------- schema-driven forms */
/* field: {k, label, type: text|number|date|time|select|check|textarea|email|month, opts: [[v,label]] | fn, req, wide, help, min, max, step} */
function fieldHtml(f, v) {
  const id = 'f_' + f.k;
  const attrs = `name="${f.k}" id="${id}" ${f.req ? 'required' : ''} ${f.min != null ? `min="${f.min}"` : ''} ${f.max != null ? `max="${f.max}"` : ''} ${f.step ? `step="${f.step}"` : ''} ${f.maxLen ? `maxlength="${f.maxLen}"` : ''} ${f.ro ? 'readonly' : ''}`;
  if (f.type === 'check') return `<label class="chk ${f.wide ? 'wide' : ''}" style="${f.wide ? 'grid-column:1/-1' : 'align-self:end'}"><input type="checkbox" ${attrs} ${v ? 'checked' : ''}> ${esc(f.label)}</label>`;
  let input;
  if (f.type === 'select') {
    const opts = typeof f.opts === 'function' ? f.opts() : f.opts;
    input = `<select class="inp" ${attrs}>${f.blank !== undefined ? `<option value="">${esc(f.blank)}</option>` : ''}${opts.map(([ov, ol]) => `<option value="${esc(ov)}" ${String(ov) === String(v ?? '') ? 'selected' : ''}>${esc(ol)}</option>`).join('')}</select>`;
  } else if (f.type === 'textarea') input = `<textarea class="inp" ${attrs}>${esc(v)}</textarea>`;
  else input = `<input class="inp" type="${f.type || 'text'}" ${attrs} value="${esc(v ?? '')}" ${f.type === 'number' ? 'inputmode="decimal"' : ''}>`;
  return `<label class="field ${f.wide ? 'wide' : ''}">${reqLabel(f)}${input}${f.help ? `<small>${esc(f.help)}</small>` : ''}</label>`;
}
const reqLabel = (f) => (f.req ? `<span>${esc(f.label)}<span class="reqm" aria-label="required"> *</span></span>` : esc(f.label));   // one line: the star stays next to the label
function readForm(form, fields) {
  const out = {};
  fields.forEach((f) => {
    const el = form.elements[f.k]; if (!el) return;
    if (f.type === 'check') out[f.k] = el.checked;
    else if (f.type === 'number') out[f.k] = el.value === '' ? '' : parseNum(el.value);
    else out[f.k] = f.maxLen ? el.value.trim().slice(0, f.maxLen) : el.value.trim();
  });
  return out;
}
/* PeopleDesk 2.13: HR's field rules for each data-entry screen (Field settings): a field the software does not
   need can be made required, and text fields can be given a longest entry. Kept on the company record as
   co.fieldRules[formId][fieldKey] = { req, max, label }. Fields the software needs stay required. */
const ruleable = (f) => !['file', 'respMatrix', 'check'].includes(f.type);
const lenable = (f) => !!f.pick || !f.type || ['text', 'textarea', 'email', 'tel'].includes(f.type);
function fieldRulesOf(formId, coId) { return ((coById(coId || CO) || {}).fieldRules || {})[formId] || {}; }
function ruled(formId, fields, coId) {
  const r = fieldRulesOf(formId, coId);
  return fields.map((f) => { const x = r[f.k]; if (!x || !ruleable(f)) return f;
    return { ...f, ...(f.req ? {} : { req: !!x.req }), ...(x.max && lenable(f) ? { maxLen: +x.max } : {}) }; });
}
/* PeopleDesk 2.13: codes given automatically (Code numbering): prefix + running number, per company and list.
   The next number follows the highest existing code with the same prefix, so codes already in use are kept. */
const NUMBERED = { depts: ['Departments', 'D', 2], desigs: ['Designations', 'DE', 2], grades: ['Grades', 'G', 2], locations: ['Locations', 'L', 2], reqs: ['Job requisitions', 'REQ-', 5] };
function numberingOf(list, coId) {
  const n = ((coById(coId || CO) || {}).numbering || {})[list] || {}; const [, prefix, digits] = NUMBERED[list];
  return { on: !!n.on, prefix: n.prefix != null ? n.prefix : prefix, digits: +n.digits || digits };
}
function nextCode(list, coId) {
  const n = numberingOf(list, coId); const co = coId || CO; const key = list === 'reqs' ? 'no' : 'code';
  let top = 0;
  (S[list] || []).filter((x) => x.companyId === co).forEach((x) => { const c = String(x[key] || ''); if (!c.startsWith(n.prefix)) return; const t = c.slice(n.prefix.length); if (/^\d+$/.test(t)) top = Math.max(top, +t); });
  return n.prefix + String(top + 1).padStart(n.digits, '0');
}
/* Generic list + edit dialog for simple records (masters). opt: {coll, title, fields, cols, filter, defaults, validate, onSave, canDelete, sort} */
function crudCard(id, opt) {
  CRUD[id] = opt;
  listOf(opt).forEach((r) => { if (!r.id) r.id = uid(); });
  const rows = (opt.rows ? opt.rows() : listOf(opt).filter(opt.filter || (() => true))).slice().sort(opt.sort || (() => 0));
  return `<div class="card"><div class="hd"><div><h2>${esc(opt.title)}</h2>${opt.sub ? `<p class="sub">${opt.sub}</p>` : ''}</div>
    ${opt.readOnly ? '' : `<button class="btn pri" data-act="crudEdit" data-crud="${id}">${esc(opt.addLabel || 'Add')}</button>`}</div>
    ${rows.length ? `<div class="scroll"><table class="t"><thead><tr>${opt.cols.map((c) => `<th class="${c.cls || ''}">${esc(c.label)}</th>`).join('')}</tr></thead><tbody>
      ${rows.map((r) => `<tr class="${opt.readOnly ? '' : 'click'}" ${opt.readOnly ? '' : `data-act="crudEdit" data-crud="${id}" data-id="${r.id}"`}>${opt.cols.map((c) => `<td class="${c.cls || ''}">${c.fmt ? c.fmt(r) : esc(r[c.k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`
      : `<div class="empty">${esc(opt.empty || 'Nothing here yet.')}</div>`}</div>`;
}
const CRUD = {};
const listOf = (opt) => (opt.arr ? opt.arr() : S[opt.coll]);
ACT_crud();
function ACT_crud() {
  ACT.crudEdit = (b) => {
    const opt = CRUD[b.dataset.crud]; const L = listOf(opt); const rec = b.dataset.id ? L.find((x) => x.id === b.dataset.id) : null;
    let v = rec || (typeof opt.defaults === 'function' ? opt.defaults() : { ...(opt.defaults || {}) });
    const num = opt.numbering && numberingOf(opt.numbering).on;
    const fields = ruled('crud.' + b.dataset.crud, opt.fields).map((f) => (num && f.k === 'code' ? { ...f, ro: true, req: false, help: rec ? 'Given automatically' : 'Given automatically when you save (Code numbering)' } : f));
    if (num && !rec) v = { ...v, code: nextCode(opt.numbering) };
    openDlg(`<form class="dlg" id="crudF" novalidate><h2>${rec ? 'Edit' : 'Add'} ${esc(opt.one || opt.title.toLowerCase())}</h2>
      <div class="form">${fields.map((f) => fieldHtml(f, v[f.k])).join('')}</div>
      <p class="err" id="crudE"></p><div class="btns">${rec && opt.canDelete !== false ? '<button type="button" class="btn danger" id="crudDel">Delete</button>' : ''}
      <button type="button" class="btn ghost" data-act="close">Cancel</button><button class="btn pri">Save</button></div></form>`, opt.wide);
    $('#crudF').onsubmit = (e) => {
      e.preventDefault();
      const data = readForm(e.target, fields);
      const miss = fields.find((f) => f.req && (data[f.k] === '' || data[f.k] == null));
      if (miss) { $('#crudE').textContent = `Enter ${miss.label.toLowerCase()}.`; return; }
      if (num) data.code = rec ? rec.code : nextCode(opt.numbering);
      if (opt.numbering && data.code) {
        const coId = (rec && rec.companyId) || CO;
        const dup = L.find((x) => x !== rec && x.companyId === coId && String(x.code || '').toLowerCase() === data.code.toLowerCase());
        if (dup) { $('#crudE').textContent = `${dup.name} already has the code ${dup.code}.`; return; }
      }
      const problem = opt.validate && opt.validate(data, rec);
      if (problem) { $('#crudE').textContent = problem; return; }
      if (rec) Object.assign(rec, data); else L.push({ id: uid(), ...(opt.base ? opt.base() : {}), ...data });
      if (opt.onSave) opt.onSave(rec || L[L.length - 1]);
      audit(`${opt.title}: ${rec ? 'changed' : 'added'}`, data.name || data.code || data.title || '');
      saveNow(); closeDlg(); toast('Saved'); route();
    };
    const del = $('#crudDel');
    if (del) del.onclick = async () => {
      const used = opt.inUse && opt.inUse(rec);
      if (used) { toast(used); return; }
      if (!(await confirmBox('Delete this?', 'This cannot be undone.', 'Delete'))) return;
      L.splice(L.indexOf(rec), 1); saveNow(); route();
    };
  };
}

/* ---------------------------------------------------------------- dialogs */
let redrawing = false;
function replaceHtml(el, html) {
  if (redrawing || !el) return false;
  redrawing = true;
  try { const a = document.activeElement; if (a && a !== document.body && el.contains(a)) a.blur(); el.innerHTML = html; } finally { redrawing = false; }
  return true;
}
function openDlg(html, wide) {
  const d = $('#dlg'); if (!replaceHtml($('#dlgBody'), html)) return; d.classList.toggle('wide', !!wide);
  if (!d.open) d.showModal();
  const f = $('#dlgBody [autofocus]') || $('#dlgBody .inp'); if (f) f.focus();
}
function closeDlg() { const d = $('#dlg'); if (d.open) d.close(); }
function confirmBox(title, text, ok = 'Confirm') {
  return new Promise((res) => {
    openDlg(`<form class="dlg" id="cf"><h2>${esc(title)}</h2><p class="mut" style="margin:0">${esc(text)}</p>
      <div class="btns"><button type="button" class="btn ghost" data-x>Cancel</button><button class="btn pri" autofocus>${esc(ok)}</button></div></form>`);
    $('#cf').onsubmit = (e) => { e.preventDefault(); closeDlg(); res(true); };
    $('#cf [data-x]').onclick = () => { closeDlg(); res(false); };
  });
}
function askText(title, label, ok = 'Save', required = true) {
  return new Promise((res) => {
    openDlg(`<form class="dlg" id="at"><h2>${esc(title)}</h2><label class="field">${esc(label)}<textarea class="inp" id="atV" autofocus></textarea></label>
      <p class="err" id="atE"></p><div class="btns"><button type="button" class="btn ghost" data-x>Cancel</button><button class="btn pri">${esc(ok)}</button></div></form>`);
    $('#at').onsubmit = (e) => { e.preventDefault(); const v = $('#atV').value.trim(); if (required && v.length < 3) { $('#atE').textContent = 'Write a few words.'; return; } closeDlg(); res(v); };
    $('#at [data-x]').onclick = () => { closeDlg(); res(null); };
  });
}

/* ---------------------------------------------------------------- Excel and files */
function writeBook(filename, sheets) {
  if (!XLSX) { toast('The Excel library did not load'); return; }
  const wb = XLSX.utils.book_new();
  Object.entries(sheets).forEach(([name, rows]) => {
    const ws = XLSX.utils.json_to_sheet(rows.length ? rows : [{ Note: 'No rows' }]);
    const keys = Object.keys(rows[0] || { Note: 1 });
    ws['!cols'] = keys.map((k) => ({ wch: Math.min(40, Math.max(10, k.length + 2, ...rows.slice(0, 200).map((r) => String(r[k] ?? '').length + 1))) }));
    XLSX.utils.book_append_sheet(wb, ws, name.slice(0, 31));
  });
  XLSX.writeFile(wb, filename);
}
