    out.late = Math.max(0, Math.round((p.in - startTs) / 60000) - (+sh.graceIn || 0));
    if (p.out) out.early = Math.max(0, Math.round((shEndTs - p.out) / 60000) - (+sh.graceOut || 0));
    const shiftHrs = (shEndTs - startTs) / 3600000;
