    if (c.calc === 'pctCTC') amt[c.code] = r2(mctc * c.value / 100);
    else if (c.calc === 'pctBasic') amt[c.code] = r2(get(basicComp.code) * c.value / 100);
    else if (c.calc === 'fixed') amt[c.code] = +c.value || 0;
