const DEFAULT_TAB = { leaveadmin: 'types', roster: 'roster', paysetup: 'comps', otpolicy: 'rules', expenses: 'mine', doctemplates: 'templates', statreg: 'pf', training: 'mine', register: 'own', payroll: 'own', masterdata: 'review', timecontrols: 'rules' };
/* contract workers or contractors in the company being worked on */
const hasContract = () => S.contractors.some((c) => c.companyId === CO) || S.employees.some((e) => e.companyId === CO && catOf(e) === 'contract');
const itemShown = (it) => !it.show || it.show();
const itemOn = (it) => (R.page === it.page && (!it.tab || (R.q.get('tab') || DEFAULT_TAB[it.page]) === it.tab)) || ({ exit: 'exits', req: 'reqs', app: 'reqs', course: 'training' }[R.page] === it.page && (!it.tab || it.tab === (R.page === 'course' ? 'calendar' : it.tab)));
const itemHref = (it) => `#/${it.page}${it.tab ? '?tab=' + it.tab : ''}`;
const allItems = () => MENU.flatMap((m) => (m.items ? m.items.map((it) => ({ ...it, group: m })) : [{ ...m, group: null }]));
/* A page may be opened when any menu item for it is visible to this person; pages without a menu item (profile/123, payroll/run) check inside */
function pageAllowed(page) { const its = allItems().filter((it) => it.page === page); return !its.length || its.some(itemShown); }
const menuOpen = () => { try { return JSON.parse(sessionStorage.getItem('pd.menu')) || {}; } catch (e) { return {}; } };
const BOTTOM = [['home', 'Home'], ['attendance', 'Attendance'], ['leave', 'Leave'], ['payslips', 'Payslips'], ['inbox', 'Approvals']];
const R = { page: 'home', arg: '', q: new URLSearchParams() };
const go = (h) => { if (location.hash === h) route(); else location.hash = h; };

/* Pages drawn by React components rather than by the HTML views below */
const REACT_PAGES = new Set(['home', 'inbox', 'settings', 'doctemplates']);
const REACT_TITLES = { home: 'Home', inbox: 'Approvals', settings: 'Settings and data', doctemplates: 'Document templates' };
/* Works out the page for a location hash: sets R, runs the page's view, and names the menu item it belongs to */
function resolvePage(hash) {
  const raw = String(hash || '').replace(/^#\/?/, '');
  const [path, query] = raw.split('?');
  const [page, arg] = path.split('/');
  R.page = page || 'home'; R.arg = arg || ''; R.q = new URLSearchParams(query || '');
  if (!(VIEWS[R.page] || REACT_PAGES.has(R.page)) || !pageAllowed(R.page)) { R.page = 'home'; R.arg = ''; R.q = new URLSearchParams(); }
  let view = null;
  if (!REACT_PAGES.has(R.page)) {
    try { view = VIEWS[R.page](); } catch (e) { console.error(e); view = { title: 'Something went wrong', html: `<div class="note bad">This page could not be shown: ${esc(e.message)}</div>` }; }
  }
  const PARENT = { exit: 'exits', req: 'reqs', app: 'reqs', payroll: 'payroll', course: 'training' };
  const cur = allItems().find(itemOn) || allItems().find((it) => it.page === R.page) || allItems().find((it) => it.page === PARENT[R.page]);
  const title = cur && cur.tab && itemOn(cur) ? cur.label : (view && view.title) || REACT_TITLES[R.page] || (cur && cur.label) || '';
  return { page: R.page, arg: R.arg, view, title, group: cur && cur.group };
}
/* Every screen calls route() after a change; React redraws */
function route() { if (me) hooks.refresh(); }

/* ---------------------------------------------------------------- events */
document.addEventListener('click', (e) => {
  const b = e.target.closest('[data-act]'); if (!b) return;
  const fn = ACT[b.dataset.act]; if (!fn) return;
  if (b.tagName === 'A' && !b.getAttribute('href')?.startsWith('#/')) e.preventDefault();
  if (b.tagName === 'A' && b.getAttribute('href') === '#') e.preventDefault();
  fn(b, e);
});
document.addEventListener('input', (e) => { const t = e.target.closest('[data-in]'); if (t && ACT[t.dataset.in]) ACT[t.dataset.in](t, e); });
document.addEventListener('change', (e) => { const t = e.target.closest('[data-ch]'); if (t && ACT[t.dataset.ch]) ACT[t.dataset.ch](t, e); });
$('#dlg').addEventListener('cancel', (e) => { e.preventDefault(); closeDlg(); });
