  [['CL', 'Casual leave', 'yearly', 12, 0, false, false, true], ['SL', 'Sick leave', 'yearly', 12, 30, false, false, true], ['EL', 'Earned leave', 'monthly', 18, 45, true, true, true],
   ['ML', 'Maternity leave', 'yearly', 182, 0, false, true, true], ['PTL', 'Paternity leave', 'yearly', 5, 0, false, true, true], ['LOP', 'Leave without pay', 'none', 0, 0, false, false, false], ['CO', 'Compensatory off', 'none', 0, 0, false, false, true]]
